def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_prev = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 45:
                    strong_prev.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    opp_count = len(alive)
    total_players = opp_count + 1

    my_need = float(WATER_REQ)
    expected_share = float(supply) / float(total_players)
    scarcity = my_need - expected_share

    if prev_bids:
        top_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
    else:
        top_prev = 50.0
        avg_prev = 50.0

    if strong_prev:
        pressure = max(sum(strong_prev) / float(len(strong_prev)), 48.0)
    else:
        pressure = max(avg_prev, 42.0)

    urgent = hp <= 3 or no_water >= 2
    semi_urgent = hp <= 5 or no_water >= 1

    if urgent:
        bid = max(pressure + 8.0, top_prev + 2.0, 62.0)
    elif scarcity >= 9:
        bid = max(pressure + 4.0, 56.0)
    elif scarcity >= 7:
        bid = max(pressure + 1.5, 49.0)
    elif scarcity >= 5:
        bid = max(avg_prev - 2.0, 41.0)
    else:
        bid = max(avg_prev - 10.0, 24.0)

    if supply <= 17:
        bid += 6.0
    elif supply <= 19:
        bid += 3.0
    elif supply >= 23:
        bid -= 5.0

    if semi_urgent:
        bid += 4.0

    if day >= 8 and hp >= 6 and no_water == 0:
        bid -= 3.0

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = DAILY_SALARY * max(0, 9 - int(day)) * 0.18
    max_affordable = max(0.0, budget - reserve_floor)
    if urgent:
        max_affordable = budget

    bid = min(bid, max_affordable if max_affordable > 0 else budget)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 40.0)
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if my_status['hp'] <= 4:
            return min(my_status['budget'], max_prev + 5.0)
        return min(my_status['budget'], max_prev * 0.95)
    return min(my_status['budget'], 65.0)
